import{_ as d}from"./plugin-vue_export-helper-DlAUqK2U.js";import{c as h,d as s,f as a,b as m,a as k,t as g,n as c,g as l,w as t,r as p,o as v,e as o}from"./app-DTv2aFsJ.js";const b={},w={id:"frontmatter-title-관련",tabindex:"-1"},f={class:"header-anchor",href:"#frontmatter-title-관련"},y={class:"table-of-contents"};function I(r,n){const i=p("VPCard"),e=p("router-link"),u=p("SiteInfo");return v(),h("div",null,[s("h1",w,[s("a",f,[s("span",null,g(r.$frontmatter.title)+" 관련",1)])]),a(i,c(l({title:"JavaScript > Article(s)",desc:"Article(s)",link:"/programming/js/articles/README.md",logo:"/images/ico-wind.svg",background:"rgba(10,10,10,0.2)"})),null,16),a(i,c(l({title:"CSS > Article(s)",desc:"Article(s)",link:"/programming/css/articles/README.md",logo:"/images/ico-wind.svg",background:"rgba(10,10,10,0.2)"})),null,16),s("nav",y,[s("ul",null,[s("li",null,[a(e,{to:"#requesting-the-user-s-location-using-geolocation"},{default:t(()=>[...n[0]||(n[0]=[o("Requesting the user’s location using <geolocation>",-1)])]),_:1})]),s("li",null,[a(e,{to:"#handling-the-geolocation-data-with-javascript"},{default:t(()=>[...n[1]||(n[1]=[o("Handling the <geolocation> data with JavaScript",-1)])]),_:1})]),s("li",null,[a(e,{to:"#falling-back-to-the-geolocation-javascript-api"},{default:t(()=>[...n[2]||(n[2]=[o("Falling back to the Geolocation JavaScript API",-1)])]),_:1})]),s("li",null,[a(e,{to:"#styling-the-geolocation-element"},{default:t(()=>[...n[3]||(n[3]=[o("Styling the <geolocation> element",-1)])]),_:1})]),s("li",null,[a(e,{to:"#what-now-what-else"},{default:t(()=>[...n[4]||(n[4]=[o("What now? What else?",-1)])]),_:1})])])]),n[5]||(n[5]=s("hr",null,null,-1)),a(u,{name:"A look at the geolocation HTML element and how it works",desc:"There’s a new HTML in town that provides a much better interface for geolocation than the older API. Daniel Schwarz is here to explain how it all works together.",url:"https://piccalil.li/blog/a-look-at-the-geolocation-html-element-and-how-it-works",logo:"https://piccalil.li/favicons/favicon.ico",preview:"https://piccalil.b-cdn.net/api/og-image?slug=a-look-at-the-geolocation-html-element-and-how-it-works/"}),n[6]||(n[6]=m(`<p>The <code>&lt;geolocation&gt;</code> HTML element does exactly what you might think it does. It’s a dedicated element that gets the user’s location, either once or continuously. The options are set using HTML attributes instead of JavaScript, but JavaScript is still needed. However, <code>&lt;geolocation&gt;</code> requires <em>fewer lines</em> of JavaScript and also offers superior error and permission handling. In fact, the <code>&lt;geolocation&gt;</code> element started off as an all-purpose <code>&lt;permission&gt;</code> element, but is now dedicated to handling geolocation.</p><p>Fewer lines of code is always a good thing, but it’s the permission prompt that’s key here. When using the aging Geolocation JavaScript API, denying permission at any point can lock the user out with no way to recover unless they change the browser or operating system permissions manually. This can be a painful experience, especially for users that aren’t tech-savvy. Plus, as developers, we have to get the Permissions API involved.</p><p>Whereas, the <code>&lt;geolocation&gt;</code> element offers:</p><ul><li>Better error handling, and where applicable, recovery handholding</li><li>User-controlled permission prompting, even if the user denied permission previously</li><li>Auto-location if the user granted permission previously</li><li>A styleable granted state via the <code>:granted</code> CSS pseudo-class</li></ul><p><code>&lt;geolocation&gt;</code> is better in every way except browser support (it requires Chrome 144+), so in this article, I’ll explain how to use it alongside the <sub>older</sub> current Geolocation JavaScript API so that users get the better experience, if the new element is available.</p><hr><h2 id="requesting-the-user-s-location-using-geolocation" tabindex="-1"><a class="header-anchor" href="#requesting-the-user-s-location-using-geolocation"><span>Requesting the user’s location using <code>&lt;geolocation&gt;</code></span></a></h2><p>The <code>&lt;geolocation&gt;</code> element accepts several attributes that largely correspond to the options of the <code>getCurrentPosition()</code> and <code>watchPosition()</code> methods of the aging Geolocation API.</p><p>Firstly, the <code>accuracymode</code> attribute accepts two values — <code>approximate</code> (which is the default value) and <code>precise</code>.</p><p><code>accuracymode=approximate</code> is equivalent to the <code>enableHighAccuracy: false</code> option (again, the default) from the Geolocation API, whereas <code>accuracymode=precise</code> is equivalent to <code>enableHighAccuracy: true</code>, which provides a more accurate location if the device is able to get one.</p><p>The <code>autolocate</code> boolean attribute attempts to get the user’s location automatically, assuming that they’ve granted the website permission previously.</p><p>The <code>watch</code> boolean attribute is equivalent to calling the <code>watchPosition()</code> method instead of the <code>getCurrentPosition()</code> method. <code>getCurrentPosition()</code> fetches the user’s location once, whereas <code>watchPosition()</code> tracks their location over time. Like <code>accuracymode=precise</code> and <code>enableHighAccuracy: true</code>, this drains the battery faster.</p><p>The <code>onlocation</code> event handler attribute can be used to execute JavaScript whenever location data or error information is passed to the browser.</p><p>What the <code>&lt;geolocation&gt;</code> element doesn’t offer, though, is the ability to specify the <code>timeout</code> (how long the browser should wait for a response) or <code>maximumAge</code> (how old a cached location can be). Instead the browser handles these as it sees fit, which is actually a good thing, because choosing the right values on a case-by-case basis is a complexity that we just don’t need.</p><p>In practice, this is how you might use <code>&lt;geolocation&gt;</code>:</p><div class="language-html line-numbers-mode" data-highlighter="prismjs" data-ext="html"><pre><code class="language-html"><span class="line"><span class="token comment">&lt;!-- Precisely autolocate and follow the user --&gt;</span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>geolocation</span> <span class="token attr-name">accuracymode</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>precise<span class="token punctuation">&quot;</span></span> <span class="token attr-name">autolocate</span> <span class="token attr-name">watch</span><span class="token punctuation">&gt;</span></span></span>
<span class="line">  <span class="token comment">&lt;!-- Render this when &lt;geolocation&gt; is unsupported --&gt;</span></span>
<span class="line">  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>fallbackButton<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Use precise location<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>geolocation</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>That is, of course, not including the JavaScript side of <code>&lt;geolocation&gt;</code> nor the Geolocation (JavaScript) API fallback. If you just want the full code then you’re looking for the <code>getCurrentPosition()</code> version and <code>watchPosition()</code> version. Note that geolocation doesn’t work in insecure contexts, so while the logic is sound, the CodePen demos won’t actually work. They’re raw-logic templates anyway, not fully working demonstrations.</p><p>Anyway, let’s get into the JavaScript of it all, starting with the JavaScript that sits on the other side of that <code>&lt;geolocation&gt;</code> markup.</p><hr><h2 id="handling-the-geolocation-data-with-javascript" tabindex="-1"><a class="header-anchor" href="#handling-the-geolocation-data-with-javascript"><span>Handling the <code>&lt;geolocation&gt;</code> data with JavaScript</span></a></h2><p>First, we want to make sure that <code>&lt;geolocation&gt;</code> is supported with <code>if (&quot;HTMLGeolocationElement&quot; in window)</code>. If it is, then we select it with <code>const geoElement = document.querySelector(&quot;geolocation&quot;)</code>.</p><p>Unfortunately, we then have to dive into the most complex part of <code>&lt;geolocation&gt;</code> — it’s validity — where the <code>isValid</code> property returns <code>true</code> or <code>false</code> and the <code>invalidReason</code> property returns <code>&quot;&quot;</code> (an empty string) or an enumerated value stating the reason.</p><p>These reasons mostly come down to developer oversight, so users <em>shouldn’t</em> encounter these ‘blockers’, but if they do, the <code>&lt;geolocation&gt;</code> button will be disabled. Here are the scenarios in which that can happen (note that the blockers are ordered by severity, and that <code>invalidReason</code> only returns the most severe one):</p><ul><li><code>illegal_subframe</code>: the <code>&lt;geolocation&gt;</code> element is nested within a <code>&lt;fencedframe&gt;</code> or insecure <code>&lt;iframe&gt;</code> (the latter of which is why the CodePen demos don’t work)</li><li><code>unsuccessful_registration</code>: the page has more than three <code>&lt;geolocation&gt;</code> elements</li><li><code>recently_attached</code>: the <code>&lt;geolocation&gt;</code> element has only recently been attached to the DOM (this blocker expires fairly quickly)</li><li><code>intersection_changed</code>: the <code>&lt;geolocation&gt;</code> element is moving</li><li><code>intersection_out_of_viewport_or_clipped</code> : the <code>&lt;geolocation&gt;</code> element isn’t within the viewport fully</li><li><code>intersection_occluded_or_distorted</code>: something is obscuring the <code>&lt;geolocation&gt;</code> element</li><li><code>style_invalid</code>: the <code>&lt;geolocation&gt;</code> element is styled in a way that isn’t allowed (more on this later)</li></ul><p>As you can see, these blockers are permanently avoidable as long as we catch and fix them. Let’s have a proper look at how <code>invalidReason</code> reports these blockers, though.</p><p>As the JavaScript comment below describes, <code>isValid</code> always returns <code>false</code> at first, while <code>invalidReason</code> returns <code>recently_attached</code>. This basically disables the <code>&lt;geolocation&gt;</code> button for a fraction of a second to prevent clickjacking. That is, unless a blocker of higher severity applies. We don’t actually need the line below, it’s there just to show you how <code>&lt;geolocation&gt;</code> will never be valid when the page loads.</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* At first, isValid === false and invalidReason === &quot;recently_attached&quot;</span>
<span class="line">unless isValid === false and invalidReason === &quot;a reason of higher severity&quot; */</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">warn</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">isValid: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>isValid<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, invalidReason: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>invalidReason<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If <code>&lt;geolocation&gt;</code> then becomes invalid for a more permanent reason, <code>isValid</code> will obviously remain <code>false</code>, so we can’t use the <code>validationstatuschange</code> event listener here. However, we can wrap the line in <code>setTimeout()</code> (as below). This will either log a new blocker into the console, or log that <code>isValid</code> is <code>true</code> (in which case <code>invalidReason</code> will be an empty string).</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* After ~300ms, when &lt;geolocation&gt; is no longer ‘recently attached’ (to the DOM)</span>
<span class="line">either isValid === true and invalidReason === &quot;&quot; (an empty string)</span>
<span class="line">or isValid === false and invalidReason === &quot;the reason with the highest severity&quot; */</span></span>
<span class="line"><span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">isValid: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>isValid<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">, invalidReason: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>invalidReason<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">300</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If the validation status changes later, <em>then</em> we can use the <code>validationstatuschange</code> event listener (again, as below). Note that if there are no persistent blockers, this will fire almost immediately as <code>invalidReason</code> switches from <code>recently_attached</code> to an empty string.</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* If the validity of &lt;geolocation&gt; changes */</span></span>
<span class="line">geoElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;validationstatuschange&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>isValid<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* &lt;geolocation&gt; is valid (if there aren’t any blockers,</span>
<span class="line">    it will become valid after it’s no longer ‘recently attached’ */</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">&lt;geolocation&gt; invalid: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>invalidReason<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Now that you know how to debug the validation status and permanently fix any persistent blockers, let’s talk about the <em>permission</em> status.</p><p>We’re given a few properties and events to work with:</p><ul><li><code>initialPermissionStatus</code>: a property that returns <code>denied</code>, <code>granted</code>, or <code>prompt</code> (i.e., neither) based on the permission status when the page first loaded</li><li><code>permissionStatus</code>: the <em>current</em> permission status</li><li><code>promptaction</code>: an event that fires when the user denies or grants permission from the <code>&lt;geolocation&gt;</code> permission prompt dialog</li><li><code>promptdismiss</code>: fires when the user dismisses the dialog, in which case the <code>permissionStatus</code> remains unchanged</li></ul><div class="language-javascript line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="js" style="--vp-collapsed-lines:15;"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* Determine the initial permission status */</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>initialPermissionStatus <span class="token operator">===</span> <span class="token string">&quot;denied&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* The user previously denied permission */</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>initialPermissionStatus <span class="token operator">===</span> <span class="token string">&quot;granted&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* The user previously granted permission */</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>initialPermissionStatus <span class="token operator">===</span> <span class="token string">&quot;prompt&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* The user hasn’t made a choice */</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* If the user denies or grants permission */</span></span>
<span class="line">geoElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;promptaction&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>permissionStatus <span class="token operator">===</span> <span class="token string">&quot;denied&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* The user denied permission */</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>permissionStatus <span class="token operator">===</span> <span class="token string">&quot;granted&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* The user granted permission */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* If the user dismisses the prompt */</span></span>
<span class="line">geoElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;promptdismiss&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>permissionStatus <span class="token operator">===</span> <span class="token string">&quot;denied&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* The permission state remained denied */</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>permissionStatus <span class="token operator">===</span> <span class="token string">&quot;granted&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* The permission state remained granted */</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>permissionStatus <span class="token operator">===</span> <span class="token string">&quot;prompt&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* The permission state remained prompt */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div><p>That being said, I honestly don’t know what we’d need any of that for. If the user previously denied permission, for example, the <code>&lt;geolocation&gt;</code> permission prompt dialog would enable the user to recover from that automatically:</p><figure><img src="https://piccalil.b-cdn.net/images/blog/geolocation-1.png?auto=format&amp;w=1500" alt="Two confirmation boxes. One reads &quot;You previously didn&#39;t allow location for this site&quot; and the other reads &quot;To use your location on this site, give Chrome access&quot;" tabindex="0" loading="lazy"><figcaption>Two confirmation boxes. One reads &quot;You previously didn&#39;t allow location for this site&quot; and the other reads &quot;To use your location on this site, give Chrome access&quot;</figcaption></figure><p>This is in contrast to the older Geolocation API, which is unlikely to help users recover. In this case we need to read the permission status, manage the state of the component accordingly, and provide recovery instructions so that users can grant access manually, but <code>&lt;geolocation&gt;</code> takes care of all of that.</p><p>What you <em>will</em> need is the new <code>location</code> event, which fires whenever the browser passes location data (<code>geoElement.position</code> in this case) or error information (<code>geoElement.error</code>) to us.</p><p>Then, in the event listener callback, assuming that <code>geoElement.position</code> is truthy, we can access <code>position.coords</code> and <code>position.timestamp</code>, synthesizing the location data like this:</p><div class="language-javascript line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="js" style="--vp-collapsed-lines:12;"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* If the browser passes location data or error information */</span></span>
<span class="line">geoElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;location&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* If location data */</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>position<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Synthesize the data */</span></span>
<span class="line">    <span class="token keyword">const</span> <span class="token punctuation">{</span></span>
<span class="line">      latitude<span class="token punctuation">,</span></span>
<span class="line">      longitude<span class="token punctuation">,</span></span>
<span class="line">      altitude<span class="token punctuation">,</span></span>
<span class="line">      accuracy<span class="token punctuation">,</span></span>
<span class="line">      altitudeAccuracy<span class="token punctuation">,</span></span>
<span class="line">      heading<span class="token punctuation">,</span></span>
<span class="line">      speed</span>
<span class="line">    <span class="token punctuation">}</span> <span class="token operator">=</span> geoElement<span class="token punctuation">.</span>position<span class="token punctuation">.</span>coords<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> timestamp <span class="token operator">=</span> geoElement<span class="token punctuation">.</span>position<span class="token punctuation">.</span>timestamp<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* If error information */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div><p>However, if <code>geoElement.error</code> is truthy, we can access <code>error.message</code> (that’s for us to log into the console) and <code>error.code</code>, which is much more suitable for error handling.</p><p>In short, there are three possible error codes, each with an associated constant so that we don’t need to remember what each error code represents. So <code>1</code> represents <code>PERMISSION_DENIED</code>, <code>2</code> represents <code>POSITION_UNAVAILABLE</code>, and finally, <code>3</code> represents <code>TIMEOUT</code>, and then we just evaluate them like this:</p><div class="language-javascript line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="js" style="--vp-collapsed-lines:12;"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* If the browser passes location data or error information */</span></span>
<span class="line">geoElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;location&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>position<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* If location data */</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* If error information */</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">&lt;geolocation&gt; error: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span>message<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span><span class="token constant">PERMISSION_DENIED</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* No HTTPS or server misconfiguration */</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span><span class="token constant">POSITION_UNAVAILABLE</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* No location source (GPS satellite or nearby Wi-Fi network/cellular tower) */</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> geoElement<span class="token punctuation">.</span>error<span class="token punctuation">.</span><span class="token constant">TIMEOUT</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* Location source detection or hardware took too long */</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div><p><code>PERMISSION_DENIED</code> means that the website isn’t being served over HTTPS (the browser denied permission), or that there’s some kind of server misconfiguration (the server denied permission), but those two errors are permanently fixable and shouldn’t occur in production.</p><p>The only way to deny permission (as far as I’m aware) is to block location access from the browser settings, then click on the <code>&lt;geolocation&gt;</code> button, then choose to continue denying. In my opinion, that’s not likely to happen and doesn’t warrant an error message anyway. There isn’t a denial mechanism for OS-level blocks so as not to make the impression that the browser can enforce one. In short, I don’t think we need to do anything for <code>PERMISSION_DENIED</code>.</p><p>And to clarify, because <code>&lt;geolocation&gt;</code> is user-invoked, <code>&lt;geolocation&gt;</code> itself never sets the permission status to denied (again, as far as I know).</p><p><code>POSITION_UNAVAILABLE</code> means that the device can’t detect a location source (nearby Wi-Fi networks and cellular towers as well as GPS satellites) to determine the location. Using a VPN or visiting the website via an in-app browser could cause this error too, so this is the trickiest error to convey to users.</p><p><code>TIMEOUT</code> means that the location source detection or hardware took too long, and that users should try again.</p><p>How you communicate errors to users is totally up to you.</p><hr><h2 id="falling-back-to-the-geolocation-javascript-api" tabindex="-1"><a class="header-anchor" href="#falling-back-to-the-geolocation-javascript-api"><span>Falling back to the Geolocation JavaScript API</span></a></h2><p>Ready for round two? Now we’re going to do the same thing but with the aging Geolocation API, which is supported in every browser, but kind of a headache.</p><p>This is where we’re at currently:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* If &lt;geolocation&gt; is supported */</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token string">&quot;HTMLGeolocationElement&quot;</span> <span class="token keyword">in</span> window<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* What we covered in the previous section */</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* What we’re focusing on now (the fallback) */</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Within that <code>else</code> block, which runs when <code>&lt;geolocation&gt;</code> isn’t supported, we start off by selecting the fallback button (<code>const fallbackButton = document.querySelector(&quot;#fallbackButton&quot;)</code>). If you recall, this is nested within <code>&lt;geolocation&gt;</code> so that it’s ignored when <code>&lt;geolocation&gt;</code> <em>is</em> supported.</p><p>After that we create a function (<code>updateState()</code>) that manages the component state and provides recovery instructions. As arguments we supply the <code>state</code> as a string (<code>‌granted</code>, <code>‌prompt</code>, or <code>‌denied</code>, corresponding with the <code>permissionStatus</code>), and optionally, <code>statusMessage</code>, which’ll be used to convey status messages to the user. I don’t want to make any assumptions about your component, so how you convey the <code>statusMessage</code> and expand upon <code>updateState()</code> is up to you.</p><p>If <code>state === &quot;denied&quot;</code>, we disable the button with <code>fallbackButton.disabled = true</code> and provide some kind of recovery instruction of which should be passed as the second argument of the function. The reason why we disable the button is that <em>this</em> Geolocation API isn’t user-invoked, so to protect the user from spam requests, the browser can suppress requests and send the API straight to jail without passing go, triggering <code>PERMISSION_DENIED</code>. Additionally, if we make the API user-invoked (as we have), users can spam the button themselves and basically shadowblock themselves, but disabling the button fixes that.</p><p>If <code>state === &quot;granted&quot;</code> or <code>state === &quot;prompt&quot;</code>, we can enable the button (<code>fallbackButton.disabled = false</code>).</p><p>Now is a good time to mention that the earlier JavaScript code for the <code>&lt;geolocation&gt;</code> element works regardless of whether the element has the <code>watch</code> attribute or not. However, when using this older Geolocation API, there are two additional things that we need to take care of when trying to keep track of the user’s location continuously. The first thing is the watcher ID, which is returned by the <code>watchPosition()</code> method. Knowing this ID enables us to clear the watcher before registering a new one, which is a must-do for performance reasons.</p><p>So we <code>let watcherID = null</code> for now, and then we create the function that attempts to get the location (<code>getLocation()</code>), and the first thing that we do within that function, assuming that <code>watcherID !== null</code> (meaning that it’s been set before), is clear the watcher using <code>navigator.geolocation.clearWatch(watcherID)</code> and make <code>watcherID = null</code> again:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* A function for getting the location */</span></span>
<span class="line"><span class="token keyword">const</span> <span class="token function-variable function">getLocation</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* If a watcher has already been registered */</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>watcherID <span class="token operator">!==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Unregister it */</span></span>
<span class="line">    navigator<span class="token punctuation">.</span>geolocation<span class="token punctuation">.</span><span class="token function">clearWatch</span><span class="token punctuation">(</span>watcherID<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    watcherID <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Then we disable the button using <code>fallbackButton.disabled = true</code> to, again, prevent spam clicks. If you want to bake some kind of loading indicator in, feel free to, but <code>&lt;geolocation&gt;</code> doesn’t.</p><p>After that we call <code>navigator.geolocation.watchPosition()</code>, setting <code>watcherID</code> to the returned watcher ID. This method has three parameters — success, error, and options.</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">watcherID <span class="token operator">=</span> navigator<span class="token punctuation">.</span>geolocation<span class="token punctuation">.</span><span class="token function">watchPosition</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token parameter">position</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Success */</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token parameter">error</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Error */</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Options */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>For the success callback function we synthesize the location data similarly to last time, then call <code>updateState(&quot;granted&quot;)</code>.</p><p>For the error callback function (optional but highly recommended) we clear the watcher and, again, make <code>watcherID = null</code>, but otherwise run the same error handling logic that <code>&lt;geolocation&gt;</code> runs. However, there are more circumstances in which the errors can occur.</p><p>For example, because <code>watchPosition()</code> and <code>getCurrentPosition()</code> aren’t necessarily user-invoked, there are more scenarios in which users are able to deny access, triggering the <code>PERMISSION_DENIED</code> error. Accordingly, we should call <code>updateState(&quot;denied&quot;, &quot;Permission denied (try this or that)&quot;)</code>, offering a useful status message and clear recovery instructions.</p><p>Similarly, <code>POSITION_UNAVAILABLE</code> can also be triggered by an OS-level block, since not all web browsers catch this during the permission prompt dialog. <code>updateState(&quot;prompt&quot;, &quot;Position unavailable (try this or that)&quot;)</code> is what we’re looking for this time.</p><p>Finally, another scenario that doesn’t occur with <code>&lt;geolocation&gt;</code> but does with <em>this</em> Geolocation API, is that if the browser prompts the user to grant permission at the OS-level, but then the user cancels their request, that can trigger the <code>TIMEOUT</code> error. Either way, call <code>updateState(&quot;prompt&quot;, &quot;Request timed out (try this or that)”)</code>, once again tweaking it to your liking.</p><p>As you can see, the error reporting isn’t the best. Sometimes the error isn’t identified correctly, and even when it is, the error can occur for various reasons, which makes it difficult for us to convey a useful status message and clear recovery instructions. <code>&lt;geolocation&gt;</code> handles this better — the errors are identified correctly, and the nature of <code>&lt;geolocation&gt;</code> ensures that certain errors never occur to begin with. But why the error categories? Why not tell us exactly what went wrong?</p><p>Well, the reason is to make fingerprinting more difficult, and while we can totally put in the extra work to pinpoint the exact problem, simply stating what happened and what the user should do next is perfectly fine. Of course, <code>error.message</code> tells us more than <code>error.code</code> does, but the messages can be a bit vague and differ in every web browser, so we can’t read them or even output them reliably.</p><p>Anyway, the optional third parameter expects an object where we can set:</p><ul><li><code>enableHighAccuracy</code>: <code>true</code> or <code>false</code></li><li><code>timeout</code>: <code>20000</code> (20 seconds) is reasonable if <code>enableHighAccuracy: true</code>, <code>3000</code> - <code>5000</code> otherwise</li><li><code>maximumAge</code>: <code>0</code> for turn-by-turn navigation, <code>5000</code> - <code>10000</code> (5-10 seconds) for live tracking, <code>300000</code> - <code>600000</code> (5-10 minutes) for frequent updates (e.g., weather)</li></ul><p>I’d rather that the web browser choose the <code>timeout</code> and <code>maximumAge</code> for us, especially considering the impact that they have on the <code>TIMEOUT</code> error and device battery, but of course, that’s exactly what <code>&lt;geolocation&gt;</code> does.</p><div class="language-javascript line-numbers-mode has-collapsed-lines collapsed" data-highlighter="prismjs" data-ext="js" style="--vp-collapsed-lines:15;"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* Attempt to get the location and store the returned ID */</span></span>
<span class="line">watcherID <span class="token operator">=</span> navigator<span class="token punctuation">.</span>geolocation<span class="token punctuation">.</span><span class="token function">watchPosition</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token comment">/* If location data is passed (like before) */</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token parameter">position</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Synthesize the data (again, like before) */</span></span>
<span class="line">    <span class="token keyword">const</span> <span class="token punctuation">{</span></span>
<span class="line">      latitude<span class="token punctuation">,</span></span>
<span class="line">      longitude<span class="token punctuation">,</span></span>
<span class="line">      altitude<span class="token punctuation">,</span></span>
<span class="line">      accuracy<span class="token punctuation">,</span></span>
<span class="line">      altitudeAccuracy<span class="token punctuation">,</span></span>
<span class="line">      heading<span class="token punctuation">,</span></span>
<span class="line">      speed</span>
<span class="line">    <span class="token punctuation">}</span> <span class="token operator">=</span> position<span class="token punctuation">.</span>coords<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">const</span> timestamp <span class="token operator">=</span> position<span class="token punctuation">.</span>timestamp<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">/* And update the state */</span></span>
<span class="line">    <span class="token function">updateState</span><span class="token punctuation">(</span><span class="token string">&quot;granted&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">/* If error information is passed (yep, like before) */</span></span>
<span class="line">  <span class="token punctuation">(</span><span class="token parameter">error</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">Geolocation error: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>error<span class="token punctuation">.</span>message<span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">/* Again, unregister the watcher (if necessary) */</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>watcherID <span class="token operator">!==</span> <span class="token keyword">null</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      navigator<span class="token punctuation">.</span>geolocation<span class="token punctuation">.</span><span class="token function">clearWatch</span><span class="token punctuation">(</span>watcherID<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">      watcherID <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> error<span class="token punctuation">.</span><span class="token constant">PERMISSION_DENIED</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* No HTTPS, server misconfiguration, or the user denied access */</span></span>
<span class="line">      <span class="token function">updateState</span><span class="token punctuation">(</span><span class="token string">&quot;denied&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Permission denied (try this or that)&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> error<span class="token punctuation">.</span><span class="token constant">POSITION_UNAVAILABLE</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* No location source (GPS satellite or nearby Wi-Fi network/cellular tower) or OS-level access */</span></span>
<span class="line">      <span class="token function">updateState</span><span class="token punctuation">(</span><span class="token string">&quot;prompt&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Position unavailable (try this or that)&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>error<span class="token punctuation">.</span>code <span class="token operator">===</span> error<span class="token punctuation">.</span><span class="token constant">TIMEOUT</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token comment">/* Location source detection or hardware took too long, or the user canceled their request */</span></span>
<span class="line">      <span class="token function">updateState</span><span class="token punctuation">(</span><span class="token string">&quot;prompt&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Request timed out (try this or that)&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">enableHighAccuracy</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">timeout</span><span class="token operator">:</span> <span class="token number">20000</span> <span class="token comment">/* 20 seconds because enableHighAccuracy: true */</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">maximumAge</span><span class="token operator">:</span> <span class="token number">0</span> <span class="token comment">/* 0 seconds because we’re demanding high accuracy */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div><div class="collapsed-lines"></div></div><p>After that we need to query the permission status using the Permissions API (<code>navigator.permissions.query({ name: &quot;geolocation&quot; }).then((permissionStatus) =&gt; { /* ... */ })</code>), and then execute all of the aforementioned logic based on that.</p><p>If <code>permissionStatus.state === &quot;granted&quot;</code>, we call <code>getLocation()</code>, which is essentially what the <code>autolocate</code> attribute does. If you don’t want autolocation, simply delete this part. If it’s anything else, we basically determine the initial state by calling <code>updateState(permissionStatus.state)</code>.</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* Query the permission status */</span></span>
<span class="line">navigator<span class="token punctuation">.</span>permissions<span class="token punctuation">.</span><span class="token function">query</span><span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;geolocation&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">permissionStatus</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">/* Equivalent to the autolocate attribute */</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>permissionStatus<span class="token punctuation">.</span>state <span class="token operator">===</span> <span class="token string">&quot;granted&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">getLocation</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* React accordingly */</span></span>
<span class="line">    <span class="token function">updateState</span><span class="token punctuation">(</span>permissionStatus<span class="token punctuation">.</span>state<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Finally, make the button respond to clicks:</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">/* If the user clicks the fallback button */</span></span>
<span class="line">fallbackButton<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&quot;click&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">getLocation</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>If we only want to get the user’s location once (rather than watch it continuously), these are the modifications that we need to make:</p><ul><li>Remove everything related to the <code>watcherID</code></li><li>Swap <code>watchPosition()</code> for <code>getCurrentPosition()</code></li><li>Provide different settings for the options parameter</li></ul><p>Note that the <code>change</code> event, which could help us update the state whenever the user changes their browser-level permission status, doesn’t fire in Safari. Besides, the standard browser behavior is to ask users to refresh the page, so let’s stick with that.</p><p>One more thing — I wanted the button to say “Refresh precise location” and “Getting precise location…” at certain points, but <code>&lt;geolocation&gt;</code> doesn’t do this, so I didn’t either. That’s up to you, though.</p><hr><h2 id="styling-the-geolocation-element" tabindex="-1"><a class="header-anchor" href="#styling-the-geolocation-element"><span>Styling the <code>&lt;geolocation&gt;</code> element</span></a></h2><p><code>&lt;geolocation&gt;</code> has a <code>:granted</code> pseudo-class. If we throw <code>:not(:granted)</code> into the mix, we can target the prompt/denied states too:</p><div class="language-css line-numbers-mode" data-highlighter="prismjs" data-ext="css"><pre><code class="language-css"><span class="line"><span class="token selector">geolocation</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token selector">&amp;:granted</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Permission granted */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">  <span class="token selector">&amp;:not(:granted)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">/* Permission not granted */</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>With the Geolocation API, we can toggle classes as needed to achieve the same effect, but honestly, I’ve never felt compeled to style such a button in this way. Personally, I’d like to be able to change the icon and text (maybe this is something that you can bake into the <code>updateState()</code> function), but this is one of the things that the <code>&lt;geolocation&gt;</code> element outright forbids.</p><figure><img src="https://piccalil.b-cdn.net/images/blog/geolocation-2.png?auto=format&amp;w=1500" alt="A button element labelled &quot;use precise location&quot;" tabindex="0" loading="lazy"><figcaption>A button element labelled &quot;use precise location&quot;</figcaption></figure><p>Before we dive into all <em>that</em>, here’s a rundown of <code>&lt;geolocation&gt;</code> rules stated by Google’s explainer and Mozilla’s explainer:</p><ul><li>There must be sufficient color contrast</li><li>The alpha channel must resolve to <code>1</code> (so no transparency)</li><li>The minimum and maximum width, height, and font size must be respected</li><li>Negative margins and outline offsets aren’t allowed either</li><li>Distortion effects — including linear gradients — are banned</li></ul><p>It’s also worth noting that some of these rules function like guardrails (for example, you physically can’t style the height above 50px), whereas others cause <code>invalidReason</code> to return <code>style_invalid</code> and the <code>&lt;geolocation&gt;</code> button to be disabled.</p><p>Some of the rules seem to have changed (or are currently bugged). <code>&lt;geolocation&gt;</code> doesn’t respect <code>prefers-color-scheme</code> either, but it’s a developing feature, so I’m not going to comment on all of that too much. I’ll just state what I do and don’t like:</p><ul><li>I don’t like that the button becomes disabled because of a style (guardrails are better, but I don’t really like either)</li><li>I don’t like the forced icon and text, and I’m also not too happy about not being able to use gradients or <code>corner-shape</code></li><li>I can make peace with everything else because I’d normally design within those guardrails anyway</li><li>The text being localized into different languages is very cool, but it’s a first for web standards and I don’t currently enjoy that it’s a thing for only these permission buttons</li></ul><p>While I obviously support preventing web authors from tricking users into giving away their location, I think it’d be better if <code>&lt;geolocation&gt;</code> were fully styleable and the permission prompt dialog be ultra clear about what the user is about to commit to.</p><p>Even though I can style the background, color, border, border radius, and box shadow how I’d want them (as in the image below, which is most of what I’d want), this feels like a step back towards unstyleable controls. Having said that, this approach means well (<em>extremely</em> well), so I can’t wait to see where this goes (and frankly, to be able to throw the aging Geolocation API in the bin).</p><figure><img src="https://piccalil.b-cdn.net/images/blog/geolocation-3.png?auto=format&amp;w=1500" alt="A purple button element with white text, labelled &quot;use precise location&quot;" tabindex="0" loading="lazy"><figcaption>A purple button element with white text, labelled &quot;use precise location&quot;</figcaption></figure><hr><h2 id="what-now-what-else" tabindex="-1"><a class="header-anchor" href="#what-now-what-else"><span>What now? What else?</span></a></h2><p>When all web browsers support <code>&lt;geolocation&gt;</code>, the user experience and developer experience will improve dramatically.</p><p>But that’s not all!</p><p>What was once the <code>&lt;permission&gt;</code> element is now the <code>&lt;geolocation&gt;</code> element, <code>&lt;install&gt;</code> element (which facilitates the installation of Progressive Web Apps), <code>&lt;usermedia&gt;</code> element (which facilitates access to the user’s camera and/or microphone), and <code>&lt;camera&gt;</code> and <code>&lt;microphone&gt;</code> elements (which facilitates access to them individually).</p><p>All of these are being trialed in Chrome as part of a larger initiative to improve the process and experience of requesting permission, which is bloody great, in my opinion.</p><hr>`,106)),k(" TODO: add ARTICLE CARD "),a(i,c(l({title:"A look at the geolocation HTML element and how it works",desc:"There’s a new HTML in town that provides a much better interface for geolocation than the older API. Daniel Schwarz is here to explain how it all works together.",link:"https://chanhi2000.github.io/bookshelf/piccalil.li/a-look-at-the-geolocation-html-element-and-how-it-works.html",logo:"https://piccalil.li/favicons/favicon.ico",background:"rgba(253,208,0,0.2)"})),null,16)])}const A=d(b,[["render",I]]),T=JSON.parse('{"path":"/piccalil.li/a-look-at-the-geolocation-html-element-and-how-it-works.html","title":"A look at the geolocation HTML element and how it works","lang":"en-US","frontmatter":{"lang":"en-US","title":"A look at the geolocation HTML element and how it works","description":"Article(s) > A look at the geolocation HTML element and how it works","icon":"fa-brands fa-js","category":["JavaScript","CSS","Article(s)"],"tag":["blog","piccalil.li","js","javascript","css"],"head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"A look at the geolocation HTML element and how it works\\",\\"image\\":[\\"https://piccalil.b-cdn.net/images/blog/geolocation-1.png?auto=format&w=1500\\",\\"https://piccalil.b-cdn.net/images/blog/geolocation-2.png?auto=format&w=1500\\",\\"https://piccalil.b-cdn.net/images/blog/geolocation-3.png?auto=format&w=1500\\"],\\"datePublished\\":\\"2026-08-20T00:00:00.000Z\\",\\"dateModified\\":null,\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Daniel Schwarz\\",\\"url\\":\\"https://piccalil.li/author/daniel-schwarz\\"}]}"],["meta",{"property":"og:url","content":"https://chanhi2000.github.io/bookshelf/piccalil.li/a-look-at-the-geolocation-html-element-and-how-it-works.html"}],["meta",{"property":"og:site_name","content":"📚Bookshelf"}],["meta",{"property":"og:title","content":"A look at the geolocation HTML element and how it works"}],["meta",{"property":"og:description","content":"Article(s) > A look at the geolocation HTML element and how it works"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://piccalil.b-cdn.net/api/og-image?slug=a-look-at-the-geolocation-html-element-and-how-it-works/"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://piccalil.b-cdn.net/api/og-image?slug=a-look-at-the-geolocation-html-element-and-how-it-works/"}],["meta",{"name":"twitter:image:alt","content":"A look at the geolocation HTML element and how it works"}],["meta",{"property":"article:author","content":"Daniel Schwarz"}],["meta",{"property":"article:tag","content":"css"}],["meta",{"property":"article:tag","content":"javascript"}],["meta",{"property":"article:tag","content":"js"}],["meta",{"property":"article:tag","content":"piccalil.li"}],["meta",{"property":"article:tag","content":"blog"}],["meta",{"property":"article:published_time","content":"2026-08-20T00:00:00.000Z"}],[{"meta":null},{"property":"og:title","content":"Article(s) > A look at the geolocation HTML element and how it works"},{"property":"og:description","content":"A look at the geolocation HTML element and how it works"},{"property":"og:url","content":"https://chanhi2000.github.io/bookshelf/piccalil.li/a-look-at-the-geolocation-html-element-and-how-it-works.html"}]],"prev":"/programming/js/articles/README.md","date":"2026-08-20T00:00:00.000Z","isOriginal":false,"author":[{"name":"Daniel Schwarz","url":"https://piccalil.li/author/daniel-schwarz"}],"cover":"https://piccalil.b-cdn.net/api/og-image?slug=a-look-at-the-geolocation-html-element-and-how-it-works/"},"git":{},"readingTime":{"minutes":14.31,"words":4294},"filePathRelative":"piccalil.li/a-look-at-the-geolocation-html-element-and-how-it-works.md","copyright":{"author":"Daniel Schwarz"}}');export{A as comp,T as data};
